// Built-in product image library: public/library/manifest.json + its webp covers
// (generated by scripts/build-image-library.mjs), and the name → cover matcher.
import test from "node:test";
import assert from "node:assert/strict";
import { existsSync, readFileSync, statSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { searchLibrary, suggestFromName } from "../src/image-library.ts";

const pub = fileURLToPath(new URL("../public", import.meta.url));
const manifest = JSON.parse(readFileSync(pub + "/library/manifest.json", "utf8"));
const items = manifest.items;
const CATEGORIES = new Set(["streaming", "music", "ai", "productivity", "storage", "vpn", "games"]);

/** Canvas size from a RIFF/WEBP header (lossy VP8, lossless VP8L or extended VP8X). */
function webpSize(buf) {
  const chunk = buf.toString("latin1", 12, 16);
  if (chunk === "VP8 ") return [buf.readUInt16LE(26) & 0x3fff, buf.readUInt16LE(28) & 0x3fff];
  if (chunk === "VP8L") {
    const bits = buf.readUInt32LE(21);
    return [(bits & 0x3fff) + 1, ((bits >> 14) & 0x3fff) + 1];
  }
  if (chunk === "VP8X") return [buf.readUIntLE(24, 3) + 1, buf.readUIntLE(27, 3) + 1];
  return [0, 0];
}

test("manifest lists about 30 brands with unique slugs and complete fields", () => {
  assert.ok(Array.isArray(items) && items.length >= 25, "expected ~30 brands, got " + items?.length);
  const slugs = items.map((i) => i.slug);
  assert.equal(new Set(slugs).size, slugs.length, "duplicate slug");
  for (const item of items) {
    assert.match(item.slug, /^[a-z0-9]+(?:-[a-z0-9]+)*$/, item.slug);
    assert.ok(item.name.trim(), item.slug + ": name");
    assert.ok(CATEGORIES.has(item.category), item.slug + ": category " + item.category);
    assert.ok(Array.isArray(item.keywords) && item.keywords.length > 0, item.slug + ": keywords");
    assert.equal(item.file, "/library/" + item.slug + ".webp");
    assert.match(item.source, /^https:\/\/(commons\.wikimedia|en\.wikipedia)\.org\/wiki\/File:/, item.slug + ": source");
    assert.ok(item.license.trim(), item.slug + ": license");
  }
});

test("every cover exists, is a 1200×1200 webp and at most 150KB; the set stays small", () => {
  let total = 0;
  for (const item of items) {
    const path = pub + item.file;
    assert.ok(existsSync(path), "missing " + item.file);
    const size = statSync(path).size;
    total += size;
    assert.ok(size <= 150 * 1024, `${item.file} is ${size} bytes`);
    const buf = readFileSync(path);
    assert.equal(buf.toString("latin1", 0, 4), "RIFF", item.file + " RIFF header");
    assert.equal(buf.toString("latin1", 8, 12), "WEBP", item.file + " WEBP header");
    assert.deepEqual(webpSize(buf), [1200, 1200], item.file + " dimensions");
  }
  assert.ok(total < 4 * 1024 * 1024, "library is " + total + " bytes");
});

test("product names suggest the right cover; unrelated names suggest nothing", () => {
  const pick = (name) => suggestFromName(items, name)?.slug ?? null;
  assert.equal(pick("Netflix Premium 4K 30 วัน"), "netflix");
  assert.equal(pick("เน็ตฟลิกซ์ จอส่วนตัว"), "netflix");
  assert.equal(pick("YouTube Music 1 เดือน"), "youtube-music");
  assert.equal(pick("YouTube Premium Family"), "youtube-premium");
  assert.equal(pick("ยูทูปพรีเมียม 1 ปี"), "youtube-premium");
  assert.equal(pick("Disney+ Hotstar"), "disney-plus");
  assert.equal(pick("Apple Music Individual"), "apple-music");
  assert.equal(pick("Apple TV+ 3 เดือน"), "apple-tv");
  assert.equal(pick("ChatGPT Plus"), "chatgpt");
  assert.equal(pick("MONOMAX 1 เดือน"), null);
  assert.equal(pick("บัตรเติมเงิน 100 บาท"), null);
  assert.equal(pick("ab"), null);
});

test("search matches English and Thai names and keywords, filtered by category", () => {
  const slugs = (q, c) => searchLibrary(items, q, c).map((i) => i.slug);
  assert.ok(slugs("netflix").includes("netflix"));
  assert.ok(slugs("NETFLIX").includes("netflix"));
  assert.ok(slugs("เน็ตฟลิกซ์").includes("netflix"));
  assert.ok(slugs("สปอติฟาย").includes("spotify"));
  assert.deepEqual(slugs("vpn").sort(), ["expressvpn", "nordvpn"]);
  assert.equal(slugs("", "all").length, items.length);
  assert.ok(slugs("", "games").every((s) => items.find((i) => i.slug === s).category === "games"));
  assert.deepEqual(slugs("netflix", "music"), []);
});
